//! Filetype definitions and detection, Lexilla style mapping and tree-sitter.
//!
//! H1.3: the filetypes and colour schemes converted from Geany 2.1.0
//! (`data/`, generated by `tools/geany-import`) are embedded in the binary.
//! A filetype is detected from the file name (Geany's patterns; the longest
//! matching pattern wins) or the shebang line; its Lexilla styles are
//! resolved against a colour scheme with Geany's semantics (named styles,
//! named colours, `fore;back;bold;italic`, `,bold`/`,italic` toggles).
//! H2.2: symbols with tree-sitter for C, C++, Rust, Python and JavaScript
//! ([`symbols`]).

#![forbid(unsafe_code)]

use std::collections::{BTreeMap, HashMap};
use std::sync::OnceLock;

use serde::Deserialize;

pub mod symbols;

mod embedded {
    include!(concat!(env!("OUT_DIR"), "/embedded.rs"));
}

/// Id of the default colour scheme (Geany's built-in one).
pub const DEFAULT_SCHEME: &str = "default";

/// A keyword list passed to the lexer.
#[derive(Debug, Clone, Deserialize, serde::Serialize)]
pub struct KeywordSet {
    /// Lexilla keyword-set index.
    pub set: u32,
    /// Geany's name for the set.
    pub key: String,
    /// Space-separated words.
    pub words: String,
}

/// A lexer style and how Geany styles it.
#[derive(Debug, Clone, Deserialize, serde::Serialize)]
pub struct StyleEntry {
    /// Lexilla style number.
    pub style: u32,
    /// Geany's name for the style.
    pub key: String,
    /// Geany style value (named style or `fore;back;bold;italic`).
    pub value: String,
    /// Whether the style extends to the end of the line.
    pub fill_eol: bool,
}

/// A filetype.
#[derive(Debug, Clone, Deserialize, serde::Serialize)]
pub struct Filetype {
    /// Stable id (`c`, `python`, …).
    pub id: String,
    /// Display name (`C`, `Python`, …).
    pub name: String,
    /// Lexilla lexer name; empty for plain text.
    pub lexer: String,
    /// File-name patterns (`*.c`, `Makefile*`).
    pub extensions: Vec<String>,
    /// Interpreter name prefixes recognised in a shebang line.
    pub interpreters: Vec<String>,
    /// Comment tokens, default extension, MIME type, word characters.
    pub settings: BTreeMap<String, String>,
    /// Indentation defaults.
    pub indentation: BTreeMap<String, String>,
    /// Lexer properties.
    pub properties: BTreeMap<String, String>,
    /// Keyword lists.
    pub keywords: Vec<KeywordSet>,
    /// Styles of the lexer.
    pub styles: Vec<StyleEntry>,
    /// Geany's build command templates (`compile`, `build`, `lint`,
    /// `execute`), split and validated by `ferny-build` (H2.4).
    #[serde(default)]
    pub build: BTreeMap<String, String>,
}

/// A named style of a colour scheme, as written.
#[derive(Debug, Clone, Deserialize, serde::Serialize)]
pub struct NamedStyleEntry {
    /// Style name (`default`, `comment`, `keyword_1`, …).
    pub name: String,
    /// Geany style value.
    pub value: String,
}

/// A colour scheme.
#[derive(Debug, Clone, Deserialize, serde::Serialize)]
pub struct ColorScheme {
    /// Stable id (`default`, `darcula`, …).
    pub id: String,
    /// Display name.
    pub name: String,
    /// Short description.
    pub description: String,
    /// Author as written by the scheme.
    pub author: String,
    /// Licence stated in the scheme's header.
    pub license: String,
    /// Named colours.
    pub colors: BTreeMap<String, String>,
    /// Named styles, in file order (later ones may refer to earlier ones).
    pub styles: Vec<NamedStyleEntry>,
}

/// A resolved style: colours as `0xRRGGBB`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Style {
    /// Foreground colour.
    pub fore: u32,
    /// Background colour.
    pub back: u32,
    /// Bold.
    pub bold: bool,
    /// Italic.
    pub italic: bool,
}

/// Geany's fallback when a scheme defines no `default`: black on white.
const FALLBACK: Style = Style {
    fore: 0x000000,
    back: 0xffffff,
    bold: false,
    italic: false,
};

/// A lexer style resolved against a scheme.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ResolvedStyle {
    /// Lexilla style number.
    pub style: u32,
    /// The resolved look.
    pub look: Style,
    /// Whether the style extends to the end of the line.
    pub fill_eol: bool,
}

pub mod user;

/// All embedded filetypes and colour schemes (plus user ones, H1.5b).
#[derive(Debug, Clone)]
pub struct Catalog {
    filetypes: Vec<Filetype>,
    schemes: Vec<ColorScheme>,
}

impl Catalog {
    /// The catalog built into Ferny, parsed once. Entries that fail to parse
    /// are skipped; `tests/catalog.rs` checks that none do.
    pub fn builtin() -> &'static Catalog {
        static CATALOG: OnceLock<Catalog> = OnceLock::new();
        CATALOG.get_or_init(|| Catalog {
            filetypes: embedded::FILETYPES
                .iter()
                .filter_map(|text| toml::from_str(text).ok())
                .collect(),
            schemes: embedded::COLOR_SCHEMES
                .iter()
                .filter_map(|text| toml::from_str(text).ok())
                .collect(),
        })
    }

    /// Number of embedded filetype and scheme files (for the tests).
    pub fn embedded_counts() -> (usize, usize) {
        (embedded::FILETYPES.len(), embedded::COLOR_SCHEMES.len())
    }

    /// Every filetype, ordered by id.
    pub fn filetypes(&self) -> &[Filetype] {
        &self.filetypes
    }

    /// Every colour scheme, ordered by id.
    pub fn schemes(&self) -> &[ColorScheme] {
        &self.schemes
    }

    /// A filetype by id.
    pub fn filetype(&self, id: &str) -> Option<&Filetype> {
        self.filetypes.iter().find(|ft| ft.id == id)
    }

    /// A colour scheme by id.
    pub fn scheme(&self, id: &str) -> Option<&ColorScheme> {
        self.schemes.iter().find(|s| s.id == id)
    }

    /// Detects the filetype as Geany 2.1.0 does: a shebang in the first
    /// line, then `-*- name -*-` in the first two lines of `header`, then the
    /// file name (longest matching pattern). `None` means plain text.
    pub fn detect(&self, file_name: &str, header: &str) -> Option<&Filetype> {
        let mut lines = header.lines();
        let first = lines.next().unwrap_or_default();
        if let Some(ft) = self.detect_shebang(first) {
            return Some(ft);
        }
        if let Some(ft) = [first, lines.next().unwrap_or_default()]
            .iter()
            .find_map(|line| self.detect_modeline(line))
        {
            return Some(ft);
        }
        self.detect_name(file_name)
    }

    /// Geany's `extract_filetype_regex` default, `-\*-\s*([^\s]+)\s*-\*-`:
    /// the word between `-*-` markers names a filetype exactly.
    fn detect_modeline(&self, line: &str) -> Option<&Filetype> {
        let mut rest = line;
        while let Some(start) = rest.find("-*-") {
            let after = rest[start + 3..].trim_start();
            let word_end = after.find(char::is_whitespace).unwrap_or(after.len());
            let (word, tail) = after.split_at(word_end);
            if !word.is_empty() && tail.trim_start().starts_with("-*-") {
                return self.filetypes.iter().find(|ft| ft.name == word);
            }
            rest = &rest[start + 3..];
        }
        None
    }

    fn detect_name(&self, file_name: &str) -> Option<&Filetype> {
        let base = file_name.rsplit(['/', '\\']).next().unwrap_or(file_name);
        let base = if cfg!(windows) {
            base.to_lowercase()
        } else {
            base.to_owned()
        };
        let mut best: Option<(&Filetype, usize)> = None;
        for ft in &self.filetypes {
            let matched = ft.extensions.iter().find(|pattern| {
                if cfg!(windows) {
                    glob_match(&pattern.to_lowercase(), &base)
                } else {
                    glob_match(pattern, &base)
                }
            });
            if let Some(pattern) = matched
                && best.is_none_or(|(_, len)| pattern.len() > len)
            {
                best = Some((ft, pattern.len()));
            }
        }
        best.map(|(ft, _)| ft)
    }

    fn detect_shebang(&self, line: &str) -> Option<&Filetype> {
        let command = line.strip_prefix("#!")?.trim();
        // Base name of the interpreter, skipping `env` and `busybox`.
        let base = command.rsplit('/').next().unwrap_or(command);
        let interpreter = base
            .strip_prefix("env ")
            .or_else(|| base.strip_prefix("busybox "))
            .unwrap_or(base)
            .trim_start();
        self.filetypes.iter().find(|ft| {
            ft.interpreters
                .iter()
                .any(|name| interpreter.starts_with(name.as_str()))
        })
    }

    /// The named styles of `scheme` resolved in order; names missing from
    /// the scheme come from the default scheme.
    pub fn named_styles(&self, scheme: &str) -> HashMap<String, Style> {
        let mut table = HashMap::new();
        if scheme != DEFAULT_SCHEME
            && let Some(default) = self.scheme(DEFAULT_SCHEME)
        {
            resolve_named(default, &mut table);
        }
        if let Some(chosen) = self.scheme(scheme).or_else(|| self.scheme(DEFAULT_SCHEME)) {
            resolve_named(chosen, &mut table);
        }
        table
    }

    /// The lexer styles of `filetype` resolved against `scheme`, plus the
    /// default style.
    pub fn resolve_styles(&self, filetype: &Filetype, scheme: &str) -> (Style, Vec<ResolvedStyle>) {
        let named = self.named_styles(scheme);
        let colors = self
            .scheme(scheme)
            .map(|s| s.colors.clone())
            .unwrap_or_default();
        let default = named.get("default").copied().unwrap_or(FALLBACK);
        let styles = filetype
            .styles
            .iter()
            .map(|entry| ResolvedStyle {
                style: entry.style,
                look: parse_style(&entry.value, default, &named, &colors),
                fill_eol: entry.fill_eol,
            })
            .collect();
        (default, styles)
    }
}

fn resolve_named(scheme: &ColorScheme, table: &mut HashMap<String, Style>) {
    // "default" first: it is the base of every other style.
    let inherited = table.get("default").copied().unwrap_or(FALLBACK);
    let base = scheme
        .styles
        .iter()
        .find(|s| s.name == "default")
        .map_or(inherited, |s| {
            parse_style(&s.value, FALLBACK, table, &scheme.colors)
        });
    table.insert("default".to_owned(), base);
    for entry in scheme.styles.iter().filter(|s| s.name != "default") {
        let style = parse_style(&entry.value, base, table, &scheme.colors);
        table.insert(entry.name.clone(), style);
    }
}

/// Parses a Geany style value (Geany's `parse_keyfile_style`).
pub fn parse_style(
    value: &str,
    base: Style,
    named: &HashMap<String, Style>,
    colors: &BTreeMap<String, String>,
) -> Style {
    let mut list: Vec<&str> = value.split(';').collect();
    if list.len() > 1 && list.last() == Some(&"") {
        list.pop();
    }
    if list.len() == 1 {
        let first = list[0];
        let name = first.split(',').next().unwrap_or_default().trim();
        if let Some(found) = named.get(name) {
            let mut style = *found;
            let modifiers = first.split_once(',').map_or("", |(_, rest)| rest);
            if modifiers.contains("bold") {
                style.bold = !style.bold;
            }
            if modifiers.contains("italic") {
                style.italic = !style.italic;
            }
            return style;
        }
        if first.contains(',') || first.trim().is_empty() {
            return base;
        }
    }
    let mut style = base;
    if let Some(fore) = list.first().and_then(|c| parse_color(c, colors)) {
        style.fore = fore;
    }
    if let Some(back) = list.get(1).and_then(|c| parse_color(c, colors)) {
        style.back = back;
    }
    if let Some(bold) = list.get(2) {
        style.bold = is_true(bold);
    }
    if let Some(italic) = list.get(3) {
        style.italic = is_true(italic);
    }
    style
}

fn is_true(text: &str) -> bool {
    matches!(text.trim(), "true" | "TRUE")
}

/// `#rgb`, `#rrggbb` or `0xrrggbb`, possibly through a named colour.
pub fn parse_color(text: &str, colors: &BTreeMap<String, String>) -> Option<u32> {
    let text = text.trim();
    let text = colors.get(text).map_or(text, String::as_str).trim();
    let hex = text
        .strip_prefix('#')
        .or_else(|| text.strip_prefix("0x"))
        .or_else(|| text.strip_prefix("0X"))?;
    if !hex.bytes().all(|b| b.is_ascii_hexdigit()) {
        return None;
    }
    match hex.len() {
        6 => u32::from_str_radix(hex, 16).ok(),
        3 => {
            let v = u32::from_str_radix(hex, 16).ok()?;
            let (r, g, b) = ((v >> 8) & 0xf, (v >> 4) & 0xf, v & 0xf);
            Some(((r * 0x11) << 16) | ((g * 0x11) << 8) | (b * 0x11))
        }
        _ => None,
    }
}

/// GLib's `g_pattern_match_simple` (`*`, `?`); see [`ferny_core::glob`].
pub fn glob_match(pattern: &str, text: &str) -> bool {
    ferny_core::glob::glob_match(pattern, text)
}
